export type Choice = { value: string; name: string };

export type Group = { group: string; name: string; options: Choice[] };

export type ConfigOption = {
  id: string;
  name: string;
  type: string;
  category?: string | null;
  currentValue: string;
  options: (Choice | Group)[];
};

export type Resolution = {
  status:
    | "missing-selector"
    | "no-request"
    | "unknown-choice"
    | "ambiguous"
    | "unchanged"
    | "change";
  selectorId: string | null;
  value: string | null;
};

export function resolveSelector(
  options: ConfigOption[],
  category: "model" | "mode" | "thought_level",
  request: string,
): Resolution {
  const selector =
    options.find(
      option => option.type === "select" && option.category === category,
    ) ??
    options.find(option => {
      if (
        option.type !== "select" ||
        (option.category !== undefined &&
          option.category !== null &&
          option.category !== "")
      ) {
        return false;
      }

      const tokens = new Set(
        (`${option.id} ${option.name}`.match(/[A-Za-z0-9]+/g) ?? []).map(
          token => token.toLowerCase(),
        ),
      );

      switch (category) {
        case "model":
          return tokens.has("model");
        case "mode":
          return (
            tokens.has("mode") ||
            (tokens.has("permission") && tokens.has("policy"))
          );
        case "thought_level":
          return (
            (tokens.has("thought") && tokens.has("level")) ||
            (tokens.has("reasoning") && tokens.has("effort"))
          );
      }
    });

  if (!selector) {
    return { status: "missing-selector", selectorId: null, value: null };
  }

  const selectorId = selector.id;
  const trimmedRequest = request.trim();

  if (trimmedRequest === "") {
    return { status: "no-request", selectorId, value: null };
  }

  const choices: Choice[] = [];
  for (const item of selector.options) {
    if ("group" in item) {
      for (const choice of item.options) {
        choices.push(choice);
      }
    } else {
      choices.push(item);
    }
  }

  const lowerRequest = trimmedRequest.toLowerCase();
  const tiers: ((choice: Choice) => boolean)[] = [
    choice => choice.value === trimmedRequest,
    choice => choice.name === trimmedRequest,
    choice => choice.value.toLowerCase() === lowerRequest,
    choice => choice.name.toLowerCase() === lowerRequest,
  ];

  for (const matches of tiers) {
    let matchedValue: string | null = null;

    for (const choice of choices) {
      if (!matches(choice)) {
        continue;
      }

      if (matchedValue !== null && matchedValue !== choice.value) {
        return { status: "ambiguous", selectorId, value: null };
      }

      matchedValue = choice.value;
    }

    if (matchedValue !== null) {
      return {
        status: matchedValue === selector.currentValue ? "unchanged" : "change",
        selectorId,
        value: matchedValue,
      };
    }
  }

  return { status: "unknown-choice", selectorId, value: null };
}
